def find_middle(s):
    if not isinstance(s, str) or len(s) == 0:
        return -1
    digits = [int(c) for c in s if c.isdigit()]
    if not digits:
        return -1
    product = 1
    for d in digits:
        product *= d
    product_str = str(product)
    mid_length = len(product_str) // 2
    if len(product_str) % 2 == 1:
        return int(product_str[mid_length])
    else:
        return int(product_str[mid_length - 1:mid_length + 1].lstrip('0') or '0')
